package com.nigson.acceptance.pricing;
import com.nigson.commerce.affiliate.*;
import com.nigson.commerce.pricing.*;
import com.nigson.commerce.platform.*;
import com.nigson.shared.events.EventCodec;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.mock.web.*;
import jakarta.servlet.http.Cookie;
import java.time.*;import java.util.*;
import static org.assertj.core.api.Assertions.*;
class AffiliateLinksTest {
 PricingFixture f;AffiliateLinks links;UUID affiliateOrg;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null);var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");var jdbc=new JdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);f=new PricingFixture(jdbc,manager);f.retail();var clock=Clock.systemUTC();links=new AffiliateLinks(jdbc,new PricingAuthority(jdbc,clock,3,"SYNTHETIC_DISTRIBUTOR_BUY"),new PlatformStore(jdbc,manager,clock,f.metrics),new AuditWriter(jdbc,clock,f.metrics),clock,manager);affiliateOrg=UUID.randomUUID();f.organizations.add(affiliateOrg);jdbc.update("INSERT INTO commerce.organization(id,created_by,updated_by,name,country_code,status) VALUES (?,'test','test','Synthetic affiliate','NG','ACTIVE')",affiliateOrg);jdbc.update("INSERT INTO commerce.organization_membership(id,created_by,updated_by,organization_id,party_id,role,status) VALUES (?,'test','test',?,?,'OWNER','ACTIVE')",UUID.randomUUID(),affiliateOrg,f.finance.party());jdbc.update("INSERT INTO commerce.account_entitlement(id,created_by,updated_by,organization_id,entitlement,status,partner_type,source_application_id,approval_command_id,activated_at) VALUES (?,'test','test',?,'AFFILIATE_MARKETING','ACTIVE','AFFILIATE',?,?,now())",UUID.randomUUID(),affiliateOrg,UUID.randomUUID(),UUID.randomUUID());}
 @AfterEach void cleanup(){if(f!=null){f.jdbc.update("DELETE FROM commerce.affiliate_visit WHERE link_id IN(SELECT id FROM commerce.affiliate_link WHERE product_id=?)",f.marketFixture.product);f.jdbc.update("DELETE FROM commerce.affiliate_link WHERE product_id=?",f.marketFixture.product);f.close();}}
 AffiliateLinks.Link link(){return links.link(f.finance,f.marketFixture.product,"product-link",UUID.randomUUID());}
 @Test void linksAreStableApprovedOnlyAndSuspensionStopsNewAttribution(){var link=link();assertThat(links.link(f.finance,f.marketFixture.product,"another-key",UUID.randomUUID())).isEqualTo(link);assertThatThrownBy(()->links.link(f.customer,f.marketFixture.product,"not-affiliate",UUID.randomUUID())).hasMessage("ACCESS_DENIED");f.jdbc.update("UPDATE commerce.account_entitlement SET status='SUSPENDED',suspended_at=now() WHERE organization_id=?",affiliateOrg);assertThat(links.status(f.finance).state()).isEqualTo("SUSPENDED");assertThatThrownBy(this::link).hasMessage("ACCESS_DENIED");assertThat(links.visit(link.code(),null).attributed()).isFalse();}
 @Test void redirectSetsSeparateSecureCookieAndKeepsOrdinaryProductDestination()throws Exception{var controller=new AffiliateLinkController(links,"test",false);var response=controller.visit(new MockHttpServletRequest("GET",link().path()),link().code());assertThat(response.getStatusCode().value()).isEqualTo(302);assertThat(response.getHeaders().getFirst("Location")).isEqualTo("/products/"+f.marketFixture.product);String cookie=response.getHeaders().getFirst("Set-Cookie");assertThat(cookie).contains("__Host-nigson-affiliate=","HttpOnly","Secure","SameSite=Lax","Max-Age=604800","Path=/").doesNotContain("nigson-session");var r=new MockHttpServletRequest();r.setCookies(new Cookie("nigson-local-affiliate",UUID.randomUUID().toString()));assertThat(AffiliateLinkController.cookie(r,false)).isNull();}
 @Test void visitExpiresSelfAndBusinessPurchasesCannotBeAttributed(){var visit=links.visit(link().code(),null);var tx=new TransactionTemplate(f.manager);assertThat(tx.<tools.jackson.databind.JsonNode>execute(s->AffiliateLinks.attribution(f.jdbc,3,visit.id(),f.customer.party(),null,Instant.now()))).isNotNull();assertThat(tx.<tools.jackson.databind.JsonNode>execute(s->AffiliateLinks.attribution(f.jdbc,3,visit.id(),f.finance.party(),null,Instant.now()))).isNull();assertThat(tx.<tools.jackson.databind.JsonNode>execute(s->AffiliateLinks.attribution(f.jdbc,3,visit.id(),f.customer.party(),affiliateOrg,Instant.now()))).isNull();assertThat(tx.<tools.jackson.databind.JsonNode>execute(s->AffiliateLinks.attribution(f.jdbc,3,visit.id(),f.customer.party(),null,Instant.now().plus(Duration.ofDays(7))))).isNull();}
 @Test void pendingOrderRetainsAttributionWhenBrowserLaterFollowsAnotherLink(){var visit=links.visit(link().code(),null);var quote=f.quotes.create(f.customer,new PricingValues.QuoteInput(f.cart,f.address,f.carrier,null,visit.id()),"tracked-order-quote",UUID.randomUUID());new TransactionTemplate(f.manager).execute(status->{UUID location=UUID.randomUUID();f.jdbc.update("INSERT INTO commerce.stock_location(id,created_by,updated_by,code,name) VALUES (?,'test','test',?,'Synthetic affiliate stock')",location,"SYNTH_"+location.toString().substring(0,8));f.jdbc.update("INSERT INTO commerce.inventory_balance(id,created_by,updated_by,sku_id,location_id,on_hand) VALUES (?,'test','test',?,?,5)",UUID.randomUUID(),f.sku,location);var clock=Clock.systemUTC();var commands=new PlatformStore(f.jdbc,f.manager,clock,f.metrics);var audit=new AuditWriter(f.jdbc,clock,f.metrics);var inventory=new com.nigson.commerce.inventory.InventoryService(new com.nigson.commerce.inventory.JdbcInventoryRepository(f.jdbc,clock),new com.nigson.commerce.inventory.InventoryAuthority(f.jdbc),commands,audit,clock,f.manager,f.jdbc,f.metrics);var stock=new com.nigson.commerce.inventory.JdbcStockLedger(f.jdbc,inventory,audit,clock);var carts=new com.nigson.commerce.cart.JdbcCartCheckout(f.jdbc,new com.nigson.commerce.cart.JdbcCartRepository(f.jdbc,clock,new JdbcPricing(f.jdbc,3)),clock,audit,f.metrics);var repository=new com.nigson.commerce.order.JdbcOrderRepository(f.jdbc,f.checkoutPricing,(CheckoutQuoteRepository)f.checkoutPricing,stock,carts,new com.nigson.commerce.order.OrderPolicy(true,"test","MOCK","SYNTHETIC_AFFILIATE_ORDER",List.of(location),900),clock);var created=repository.checkout(f.customer,new com.nigson.commerce.order.OrderValues.CheckoutInput(quote.id(),quote.quoteHash(),"HOSTED"),UUID.randomUUID());UUID order=created.checkout().order().id();String frozen=f.jdbc.queryForObject("SELECT commercial_snapshot::text FROM commerce.sales_order WHERE id=?",String.class,order);assertThat(EventCodec.JSON.readTree(frozen).path("affiliateAttribution").path("affiliatePartyId").asString()).isEqualTo(f.finance.party().toString());links.visit(link().code(),visit.id());assertThat(f.jdbc.queryForObject("SELECT commercial_snapshot::text FROM commerce.sales_order WHERE id=?",String.class,order)).isEqualTo(frozen);status.setRollbackOnly();return null;});}
 @Test void checkoutControllerUsesOnlyTheHttpOnlyVisitCookie()throws Exception {var visit=links.visit(link().code(),null);var request=new MockHttpServletRequest("POST","/api/v1/checkout/quotes");request.addHeader("Idempotency-Key","cookie-checkout");request.setCookies(new Cookie("__Host-nigson-affiliate",visit.id().toString()));var controller=new PricingController(f.books,f.prices,f.quotes,f.assignments);var body=EventCodec.JSON.valueToTree(f.quoteInput());assertThat(body.has("affiliateVisitId")).isFalse();((tools.jackson.databind.node.ObjectNode)body).remove("couponCode");try{org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(org.springframework.security.authentication.UsernamePasswordAuthenticationToken.authenticated(f.customer,null,List.of()));var quote=controller.quote(request,body).getBody();var saved=EventCodec.JSON.readTree(f.jdbc.queryForObject("SELECT price_snapshot::text FROM commerce.checkout_quote WHERE id=?",String.class,quote.id()));assertThat(saved.path("affiliateAttribution").path("affiliatePartyId").asString()).isEqualTo(f.finance.party().toString());}finally{org.springframework.security.core.context.SecurityContextHolder.clearContext();}}
 @Test void latestValidLinkReplacesPreviousAffiliateInTheSameBrowser(){var visit=links.visit(link().code(),null);UUID secondOrg=UUID.randomUUID();f.organizations.add(secondOrg);var identity=f.marketFixture.adminActor;f.jdbc.update("INSERT INTO commerce.organization(id,created_by,updated_by,name,country_code,status) VALUES (?,'test','test','Synthetic second affiliate','NG','ACTIVE')",secondOrg);f.jdbc.update("INSERT INTO commerce.organization_membership(id,created_by,updated_by,organization_id,party_id,role,status) VALUES (?,'test','test',?,?,'OWNER','ACTIVE')",UUID.randomUUID(),secondOrg,identity.party());f.jdbc.update("INSERT INTO commerce.account_entitlement(id,created_by,updated_by,organization_id,entitlement,status,partner_type,source_application_id,approval_command_id,activated_at) VALUES (?,'test','test',?,'AFFILIATE_MARKETING','ACTIVE','AFFILIATE',?,?,now())",UUID.randomUUID(),secondOrg,UUID.randomUUID(),UUID.randomUUID());var actor=new com.nigson.shared.security.ActorAssertion.Actor(identity.party(),identity.identityIssuer(),identity.identitySubject(),null,Set.of("CUSTOMER"),Set.of(),null);var next=links.link(actor,f.marketFixture.product,"second-affiliate-link",UUID.randomUUID());assertThat(links.visit(next.code(),visit.id()).id()).isEqualTo(visit.id());var attribution=new TransactionTemplate(f.manager).<tools.jackson.databind.JsonNode>execute(s->AffiliateLinks.attribution(f.jdbc,3,visit.id(),f.customer.party(),null,Instant.now()));assertThat(attribution.path("affiliatePartyId").asString()).isEqualTo(identity.party().toString());}
 @Test void checkoutFreezesAttributionAndRevalidatesChangedVisits(){var link=link();var visit=links.visit(link.code(),null);var input=new PricingValues.QuoteInput(f.cart,f.address,f.carrier,null,visit.id());var quote=f.quotes.create(f.customer,input,"tracked-checkout",UUID.randomUUID());String saved=f.jdbc.queryForObject("SELECT price_snapshot::text FROM commerce.checkout_quote WHERE id=?",String.class,quote.id());assertThat(EventCodec.JSON.readTree(saved).path("affiliateAttribution").path("affiliatePartyId").asString()).isEqualTo(f.finance.party().toString());new TransactionTemplate(f.manager).execute(s->f.checkoutPricing.require(f.customer,quote.id(),quote.quoteHash()));assertThat(links.visit(link.code(),visit.id()).id()).isEqualTo(visit.id());assertThatThrownBy(()->new TransactionTemplate(f.manager).execute(s->f.checkoutPricing.require(f.customer,quote.id(),quote.quoteHash()))).hasMessage("CHECKOUT_REPRICE_REQUIRED");assertThat(f.jdbc.queryForObject("SELECT price_snapshot::text FROM commerce.checkout_quote WHERE id=?",String.class,quote.id())).isEqualTo(saved);}
}
